<template>
  <div class="flow-standalone-root" :style="rootStyle">
    <!-- 操作コントローラー（showControls: true の場合） -->
    <div v-if="showControls" class="standalone-controls">
      <div class="controls-left">
        <button
          v-if="!isPlaying"
          type="button"
          class="ctrl-btn play-btn"
          @click="playScenario"
          title="台本アニメーションを再生"
        >
          ▶️ 再生
        </button>
        <button
          v-else
          type="button"
          class="ctrl-btn stop-btn"
          @click="stopScenario"
          title="再生を停止"
        >
          ⏹️ 停止
        </button>

        <button
          type="button"
          class="ctrl-btn"
          :disabled="isPlaying || currentStepIndex <= 0"
          @click="prevStep"
          title="1ステップ戻る"
        >
          ⏮️
        </button>
        <button
          type="button"
          class="ctrl-btn"
          :disabled="isPlaying || currentStepIndex >= scenarioSteps.length - 1"
          @click="nextStep"
          title="1ステップ進む"
        >
          ⏭️
        </button>

        <button
          type="button"
          class="ctrl-btn reset-btn"
          @click="resetScenario"
          title="初期状態にリセット"
        >
          🔄 リセット
        </button>

        <span class="step-badge" v-if="scenarioMode">
          {{ currentStepIndex }} / {{ scenarioSteps.length - 1 }}
        </span>
      </div>

      <div class="controls-status" v-if="statusText">
        <span class="status-dot"></span>
        <span class="status-label">{{ statusText }}</span>
      </div>
    </div>

    <!-- SVGコンテナ -->
    <div
      ref="containerRef"
      class="flow-wrapper"
      :class="[
        {
          'is-paused': paused,
          'scenario-mode': scenarioMode,
          'show-frame-borders': showFrameBorders
        },
        stepClassList
      ]"
      v-html="processedSvg"
    ></div>
  </div>
</template>

